<script setup lang="ts">
import { onMounted,ref } from 'vue'; import { api } from '../api';
const cfg=ref<any>({rankDim:'WEEK',rankRange:3,prizeMap:{1:'TREASURE_DIAMOND',2:'TREASURE_GOLD',3:'TREASURE_SILVER'},teamReward:true,teamCard:'TREASURE_TEAM',stack:true,reqShard:true,settleCap:20}),tpls=ref<any[]>([]),msg=ref('');
async function load(){const d=await api<any>('/admin/settlement-config');cfg.value={...cfg.value,...d.cfg,prizeMap:{...cfg.value.prizeMap,...(d.cfg.prizeMap||{})}};tpls.value=d.templates||[]}async function save(){try{await api('/admin/settlement-config',{method:'PUT',body:{data:cfg.value}});msg.value='规则已保存'}catch(e:any){msg.value=e.message}} onMounted(load);
</script>
<template><div><div class="hdr">榜单与奖励规则 <em>影响 C 端榜单口径与周/月结算发放</em></div><div v-if="msg" class="notice">{{msg}}</div><section class="card"><div class="st">榜单统计口径</div><button class="btn" :class="{ghost:cfg.rankDim!=='WEEK'}" @click="cfg.rankDim='WEEK'">周维度</button><button class="btn" :class="{ghost:cfg.rankDim!=='MONTH'}" @click="cfg.rankDim='MONTH'">月维度</button><div class="note">切换后 C 端榜单的“当周新增 / 当月累计”同步变化；碎片按当月对局聚合，积分取当月累计，冠军取当月夺冠数。</div></section><section class="card"><div class="st">个人奖励 <em>名次占位制，超出范围不发</em></div><label>发放名次范围<input v-model.number="cfg.rankRange" type="number" min="1" max="20" class="inp small" /> 名</label><div class="prizes"><label v-for="n in cfg.rankRange" :key="n">第 {{n}} 名<select v-model="cfg.prizeMap[n]" class="inp"><option v-for="t in tpls" :key="t.id" :value="t.sub">{{t.name}}</option></select></label></div></section><section class="card"><div class="st">战队奖励</div><label class="switch">夺冠战队奖励<input v-model="cfg.teamReward" type="checkbox" /></label><label>奖励卡型<select v-model="cfg.teamCard" class="inp"><option v-for="t in tpls" :key="t.id" :value="t.sub">{{t.name}}</option></select></label><label class="switch">本人需有碎片<input v-model="cfg.reqShard" type="checkbox" /></label></section><section class="card"><div class="st">奖励叠加</div><label class="switch">同一用户战队奖 + 个人奖可同发<input v-model="cfg.stack" type="checkbox" /></label></section><section class="card"><div class="st">结算发放上限</div><label>单次自动结算发放卡券总张数上限<input v-model.number="cfg.settleCap" type="number" min="1" max="100" class="inp small" /></label></section><button class="btn" @click="save">保存规则</button><div class="note">规则以结算时快照为准，修改不会回溯已发放或已撤销的历史周次。</div></div></template>
<style scoped>.card{margin-bottom:12px}.btn+.btn{margin-left:8px}.notice{color:var(--green);font-size:12px;margin-bottom:8px}.small{width:100px;display:inline-block;margin:0 6px}.prizes{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin-top:12px}.prizes label,.card>label{display:block;color:var(--ink2);font-size:12px}.prizes .inp,.card>label .inp{margin-top:5px}.switch{display:flex!important;justify-content:space-between;align-items:center;padding:10px 0;border-bottom:1px solid var(--line);font-size:14px!important;color:var(--ink)!important}</style>
